B.a1S=s(["\ubcf8\uc778\uc740 \uc2a4\ucfe0\ubc84\ub2e4\uc774\ube59\uc774 \uc218\uc911\uc5d0\uc11c \uc555\ucd95\ub41c \ud638\ud761 \uae30\uccb4\ub97c \uc0ac\uc6a9\ud558\uc5ec \uc774\ub8e8\uc5b4\uc9c0\ub294 \ud65c\ub3d9\uc774\uba70, \ucda9\ubd84\ud55c \uad50\uc721\uacfc \uc548\uc804\uad00\ub9ac\uac00 \uc774\ub8e8\uc5b4\uc9c0\ub294 \uacbd\uc6b0\uc5d0\ub3c4 \ud2b9\uc815 \uc704\ud5d8\uc774 \uc644\uc804\ud788 \uc81c\uac70\ub420 \uc218 \uc5c6\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \ub2e4\uc74c\uacfc \uac19\uc740 \uc704\ud5d8\uc774 \ubc1c\uc0dd\ud560 \uc218 \uc788\uc74c\uc744 \uc778\uc9c0\ud569\ub2c8\ub2e4."],t.s)
B.a3d=s(["\uc218\uc555 \ubcc0\ud654\uc5d0 \ub530\ub978 \uadc0, \ubd80\ube44\ub3d9, \ud3d0 \ub4f1\uc758 \uc555\ub825 \uc190\uc0c1","\uac10\uc555\ubcd1, \ub3d9\ub9e5\uac00\uc2a4\uc0c9\uc804\uc99d \ubc0f \uae30\ud0c0 \uc7a0\uc218 \uad00\ub828 \uc9c8\ud658","\ud638\ud761 \uae30\uccb4 \uacf5\uae09 \ubb38\uc81c, \uc7a5\ube44 \uace0\uc7a5 \ubc0f \uc0ac\uc6a9\uc0c1\uc758 \uc624\ub958","\uc218\uc911 \ubc29\ud5a5\uac10\uac01 \uc0c1\uc2e4, \uc2dc\uc57c \uc81c\ud55c, \ud574\ub958 \ubc0f \uc218\uc628 \ubcc0\ud654","\ubd80\ub825 \uc870\uc808 \ubb38\uc81c, \ube44\uc0c1\uc0c1\ud669 \ubc0f \uc608\uae30\uce58 \ubabb\ud55c \uc218\uc911 \ud658\uacbd \ubcc0\ud654","\uc2e0\uccb4\uc801 \ud53c\ub85c, \uc2ec\ub9ac\uc801 \uc2a4\ud2b8\ub808\uc2a4 \ubc0f \uac74\uac15 \uc0c1\ud0dc\uc640 \uad00\ub828\ub41c \uc704\ud5d8","\uc2e0\uc18d\ud55c \uad6c\uc870 \ub610\ub294 \uc804\ubb38 \uc758\ub8cc\uae30\uad00\uc73c\ub85c\uc758 \uc774\uc1a1\uc774 \uc5b4\ub824\uc6b4 \ud658\uacbd\uc801 \uc704\ud5d8"],t.s)
B.arY=new A.ep("\uc81c2\uc870. \uc2a4\ucfe0\ubc84\ub2e4\uc774\ube59\uc758 \uc704\ud5d8\uc5d0 \ub300\ud55c \uc778\uc9c0",B.a1S,B.a3d)
B.a_w=s(["\ubcf8\uc778\uc740 \ub2e4\uc774\ube59 \ucc38\uac00\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce60 \uc218 \uc788\ub294 \ubcf8\uc778\uc758 \uac74\uac15 \uc0c1\ud0dc\ub97c \uc815\ud655\ud558\uac8c \uace0\uc9c0\ud560 \ucc45\uc784\uc774 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \ubcc4\ub3c4\ub85c \uc81c\uacf5\ub418\ub294 \ub2e4\uc774\ubc84 \uac74\uac15\uc9c4\uc220\uc11c \ub610\ub294 \uc758\ud559\uc801 \ud3c9\uac00 \uc808\ucc28\uc5d0 \uc131\uc2e4\ud558\uac8c \uc751\ud558\uace0, \uc758\ud559\uc801 \ud655\uc778\uc774 \ud544\uc694\ud55c \uacbd\uc6b0 \uc801\uc808\ud55c \ud655\uc778\uc744 \ubc1b\uc740 \ud6c4 \ucc38\uac00\ud558\uaca0\uc2b5\ub2c8\ub2e4.","\uad50\uc721 \uc911 \uac74\uac15 \uc0c1\ud0dc\uac00 \ubcc0\ud558\uac70\ub098 \uc2e0\uccb4\uc801 \uc774\uc0c1\uc774 \ubc1c\uc0dd\ud558\ub294 \uacbd\uc6b0 \uc989\uc2dc \uac15\uc0ac\uc5d0\uac8c \uc54c\ub9ac\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
B.as2=new A.ep("\uc81c3\uc870. \uac74\uac15 \uc0c1\ud0dc\uc758 \ud655\uc778",B.a_w,B.C)
B.a23=s(["\ubcf8\uc778\uc740 APDI \uad50\uc721\uacfc\uc815\uc5d0 \ucc38\uac00\ud558\uba74\uc11c \ub2f4\ub2f9 \uac15\uc0ac\uc758 \uc548\uc804\uad50\uc721, \uad50\uc721 \ubc94\uc704, \uc218\uc911\ud65c\ub3d9 \uacc4\ud68d \ubc0f \ube44\uc0c1\uc0c1\ud669 \uc9c0\uce68\uc744 \uc900\uc218\ud558\uaca0\uc2b5\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uad50\uc721\uacfc\uc815\uc5d0\uc11c \uc694\uad6c\ud558\ub294 \uc548\uc804\uc218\uce59, \uc7a5\ube44 \uc810\uac80, \ubc84\ub514 \uc2dc\uc2a4\ud15c, \uc218\uc911 \uc758\uc0ac\uc18c\ud1b5 \ubc0f \ube44\uc0c1\uc808\ucc28\uc758 \uc911\uc694\uc131\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc790\uc2e0\uc758 \uad50\uc721 \uc218\uc900, \uacbd\ud5d8 \ubc0f \uc2e0\uccb4\uc801 \ub2a5\ub825\uc744 \ucd08\uacfc\ud558\ub294 \ud65c\ub3d9\uc744 \uc784\uc758\ub85c \uc218\ud589\ud558\uc9c0 \uc54a\uc73c\uba70, \uc704\ud5d8\ud558\ub2e4\uace0 \ud310\ub2e8\ub418\ub294 \uc0c1\ud669\uc5d0\uc11c\ub294 \ud65c\ub3d9\uc758 \uc911\ub2e8\uc744 \uc694\uccad\ud560 \uc218 \uc788\uc74c\uc744 \ud655\uc778\ud569\ub2c8\ub2e4."],t.s)
B.as7=new A.ep("\uc81c4\uc870. \uad50\uc721 \ubc0f \uc548\uc804\uc218\uce59 \uc900\uc218",B.a23,B.C)
B.a19=s(["\ubcf8\uc778\uc740 APDI\uac00 \ub2e4\uc774\ubc84 \uad50\uc721\uacfc\uc815\uc758 \uae30\uc900\uacfc \uad50\uc721\uccb4\uacc4\ub97c \uc218\ub9bd\ud558\ub294 \uc804\ubb38 \uad50\uc721\ub2e8\uccb4\uc774\uba70, \uac1c\ubcc4 \uad50\uc721\uae30\uad00\uacfc \uac15\uc0ac\ub294 \ubcc4\ub3c4\uc758 \uc0ac\uc5c5\uc790\ub85c \ud65c\ub3d9\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\uac01 \uae30\uad00\uacfc \uac15\uc0ac\uc758 \uad6c\uccb4\uc801\uc778 \ucc45\uc784\uc740 \uc2e4\uc81c \uc6b4\uc601\uad00\uacc4, \uad50\uc721\uacc4\uc57d, \uad00\ub828 \ubc95\ub839 \ubc0f \uac1c\ubcc4 \uc0ac\uc2e4\uad00\uacc4\uc5d0 \ub530\ub77c \ud310\ub2e8\ub420 \uc218 \uc788\uc74c\uc744 \uc778\uc815\ud569\ub2c8\ub2e4."],t.s)
B.arV=new A.ep("\uc81c5\uc870. \uad50\uc721\uae30\uad00\uacfc APDI\uc758 \uad00\uacc4",B.a19,B.C)
B.a1W=s(["\ubcf8\uc778\uc740 \uc2a4\ucfe0\ubc84\ub2e4\uc774\ube59\uc5d0 \uc218\ubc18\ub418\ub294 \uc77c\ubc18\uc801\uc774\uace0 \uace0\uc720\ud55c \uc704\ud5d8\uc5d0 \uad00\ud55c \uc124\uba85\uc744 \ub4e4\uc5c8\uc73c\uba70, \uc774\ub97c \uc774\ud574\ud55c \uc0c1\ud0dc\uc5d0\uc11c \uc790\ubc1c\uc801\uc73c\ub85c \uad50\uc721 \ubc0f \ud65c\ub3d9\uc5d0 \ucc38\uac00\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uad50\uc721\uae30\uad00\uacfc \uac15\uc0ac\uac00 \ud569\ub9ac\uc801\uc778 \uc548\uc804\uc870\uce58\ub97c \uc774\ud589\ud558\ub354\ub77c\ub3c4 \ubaa8\ub4e0 \uc0ac\uace0\ub97c \uc608\ubc29\ud560 \uc218\ub294 \uc5c6\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ub2e4\ub9cc, \ubcf8 \ub3d9\uc758\ub294 \uad00\uacc4 \ubc95\ub839\uc5d0 \ub530\ub77c \uc778\uc815\ub418\ub294 \uc815\ub2f9\ud55c \uad8c\ub9ac\ub098 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc744 \ud3ec\uad04\uc801\uc73c\ub85c \ud3ec\uae30\ud558\ub294 \uac83\uc744 \uc758\ubbf8\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."],t.s)
B.arS=new A.ep("\uc81c6\uc870. \uc790\ubc1c\uc801 \ucc38\uac00 \ubc0f \uc704\ud5d8 \uc218\uc6a9",B.a1W,B.C)
B.a0A=s(["\ubcf8\uc778\uc740 \ub2e4\uc774\ube59\uc5d0 \ubcf8\uc9c8\uc801\uc73c\ub85c \uc218\ubc18\ub418\ub294 \uc704\ud5d8 \ubc0f \ubcf8\uc778\uc758 \uc548\uc804\uc218\uce59 \uc704\ubc18 \ub4f1\uc73c\ub85c \ubc1c\uc0dd\ud560 \uc218 \uc788\ub294 \uacb0\uacfc\ub97c \uc778\uc9c0\ud569\ub2c8\ub2e4.","\uadf8\ub7ec\ub098 APDI, \uad50\uc721\uae30\uad00, \uac15\uc0ac, \ub2e4\uc774\ube0c\ub9c8\uc2a4\ud130 \ubc0f \uad00\ub828\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc5d0 \ub530\ub978 \ubc95\uc801 \ucc45\uc784\uc740 \uad00\uacc4 \ubc95\ub839\uc5d0 \ub530\ub77c \ud310\ub2e8\ub418\uba70, \ubcf8 \ub3d9\uc758\uc11c\ub9cc\uc73c\ub85c \ub2f9\uc5f0\ud788 \uba74\uc81c\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\ubcf8 \ub3d9\uc758\uc11c\uc758 \uc77c\ubd80 \uc870\ud56d\uc774 \ubc95\ub839\uc5d0 \uc704\ubc18\ub418\uc5b4 \ud6a8\ub825\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub354\ub77c\ub3c4 \ub098\uba38\uc9c0 \uc870\ud56d\uc758 \ud6a8\ub825\uc740 \uad00\ub828 \ubc95\ub839\uc5d0 \ub530\ub77c \ud310\ub2e8\ub429\ub2c8\ub2e4."],t.s)
B.as6=new A.ep("\uc81c7\uc870. \ucc45\uc784\uc758 \ubc94\uc704",B.a0A,B.C)
B.a1F=s(["\ubcf8\uc778\uc740 \ub2e4\uc774\ube59 \uc7a5\uc18c\uc758 \ud2b9\uc131\uc5d0 \ub530\ub77c \uc751\uae09\uc758\ub8cc\uc2dc\uc124 \ubc0f \uc7ac\uc555\uce58\ub8cc\uc2dc\uc124\uc5d0 \ub300\ud55c \uc811\uadfc\uc774 \uc9c0\uc5f0\ub420 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\uc751\uae09\uc0c1\ud669 \ubc1c\uc0dd \uc2dc \uad50\uc721\uae30\uad00 \ub610\ub294 \uad6c\uc870 \ub2f4\ub2f9\uc790\uac00 \uc801\uc808\ud55c \uad6c\uc870 \uc694\uccad, \uc751\uae09\ucc98\uce58 \ubc0f \uc758\ub8cc\uae30\uad00 \uc774\uc1a1\uc744 \uc704\ud55c \uc870\uce58\ub97c \uc218\ud589\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud558\uace0 \uc774\uc5d0 \ub3d9\uc758\ud569\ub2c8\ub2e4.","\uc774 \uc870\ud56d\uc740 \ubc95\ub839\uc0c1 \uc694\uad6c\ub418\ub294 \ubcc4\ub3c4\uc758 \uc758\ub8cc \ub3d9\uc758\ub97c \ub300\uc2e0\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."],t.s)
B.as1=new A.ep("\uc81c8\uc870. \uc751\uae09\uc0c1\ud669\uc5d0 \ub300\ud55c \uc774\ud574",B.a1F,B.C)
B.a1M=s(["\ubcf8\uc778\uc740 \ubcf8 \ub3d9\uc758\uc11c\uc758 \uc804\uccb4 \ub0b4\uc6a9\uc744 \uc77d\uace0 \uc774\ud574\ud558\uc600\uc73c\uba70, \uad81\uae08\ud55c \uc0ac\ud56d\uc5d0 \ub300\ud574 \uc124\uba85\uc744 \uc694\uccad\ud560 \uae30\ud68c\ub97c \uac00\uc84c\uc2b5\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uac15\uc694 \uc5c6\uc774 \uc790\ubc1c\uc801\uc778 \uc758\uc0ac\ub85c \ubcf8 \ub3d9\uc758\uc11c\uc5d0 \uc11c\uba85\ud569\ub2c8\ub2e4."],t.s)
B.asb=new A.ep("\uc81c9\uc870. \ucd5c\uc885 \ud655\uc778",B.a1M,B.C)
